    const length = heap.length;
    while (true) {
      let smallest = index;
      const left = 2 * index + 1;
      const right = 2 * index + 2;
      if (left < length && heap[left].priorite < heap[smallest].priorite) {
        smallest = left;
      }
      if (right < length && heap[right].priorite < heap[smallest].priorite) {
        smallest = right;
      }
      if (smallest === index) break;
      [heap[index], heap[smallest]] = [heap[smallest], heap[index]];
