            descriptor.set.call(cible, value);
            return true;
          }
          return false;
        },
        enumerable: descriptor.enumerable,
        configurable: descriptor.configurable
      });
    } else {
      // Data property
      Object.defineProperty(proxy, prop, {
        get() {
          if (gestionnaire.get) {
            return gestionnaire.get(cible, prop, proxy);
          }
          return cible[prop];
