async function executerEnPool(taches, concurrence) {
  const results = new Array(taches.length);
  let index = 0;
  let running = 0;

  return new Promise((resolve, reject) => {
    function next() {
      while (running < concurrence && index < taches.length) {
        const i = index++;
        running++;
        Promise.resolve(taches[i]()).then(
          (value) => {
            results[i] = value;
            running--;
            next();
          },
          (err) => {
            reject(err);
          }
        );
      }
      if (running === 0 && index >= taches.length) {
        resolve(results);
      }
    }
    next();
  });
}
