function creerSubject() {
  const observers = [];
  let stopped = false;
  let stopValue = null;

  function notify(observer, type, value) {
    if (observer && typeof observer[type] === 'function') {
      try {
        observer[type](value);
      } catch (e) {
        // Ignore errors in observer callbacks to not break other observers
      }
    }
  }

  return {
    next(value) {
      if (stopped) return;
      for (const obs of observers) {
        notify(obs, 'next', value);
      }
    },
    error(err) {
      if (stopped) return;
      stopped = true;
      stopValue = { type: 'error', value: err };
      for (const obs of observers) {
        notify(obs, 'error', err);
      }
      observers.length = 0;
    },
    complete() {
      if (stopped) return;
      stopped = true;
      stopValue = { type: 'complete' };
      for (const obs of observers) {
        notify(obs, 'complete');
      }
      observers.length = 0;
    },
    subscribe(observer) {
      if (stopped) {
        if (stopValue.type === 'error') {
          notify(observer, 'error', stopValue.value);
        } else {
          notify(observer, 'complete');
        }
        return { unsubscribe: () => {} };
      }
      observers.push(observer);
      return {
        unsubscribe() {
          const idx = observers.indexOf(observer);
          if (idx !== -1) observers.splice(idx, 1);
        }
      };
    }
  };
}
