function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  let state = 'closed';
  let failureCount = 0;
  let timeoutId = null;

  function resetTimeout() {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
  }

  function tripOpen() {
    state = 'open';
    resetTimeout();
    timeoutId = setTimeout(() => {
      state = 'half-open';
      timeoutId = null;
    }, delaiResetMs);
  }

  function onSuccess() {
    failureCount = 0;
    if (state === 'half-open') {
      state = 'closed';
    }
  }

  function onFailure() {
    failureCount++;
    if (state === 'half-open') {
      tripOpen();
    } else if (state === 'closed' && failureCount >= seuil) {
      tripOpen();
    }
  }

  const wrapped = async function(...args) {
    if (state === 'open') {
      throw new Error('Circuit breaker is open');
    }
    try {
      const result = await fn(...args);
      onSuccess();
      return result;
    } catch (err) {
      onFailure();
      throw err;
    }
  };

  wrapped.getState = () => state;
  wrapped.reset = () => {
    state = 'closed';
    failureCount = 0;
    resetTimeout();
  };

  return wrapped;
}
```

