async function executerEnPool(taches, concurrence) {
  if (concurrence <= 0) throw new Error("Concurrence doit être > 0");
  const results = new Array(taches.length);
  let index = 0;
  const executing = [];

  async function runTask(task, i) {
    try {
      const value = await task();
      results[i] = { status: 'fulfilled', value };
    } catch (reason) {
      results[i] = { status: 'rejected', reason };
    }
  }

  async function worker() {
    while (index < taches.length) {
      const i = index++;
      await runTask(taches[i], i);
    }
  }

  for (let i = 0; i < Math.min(concurrence, taches.length); i++) {
    executing.push(worker());
  }

  await Promise.all(executing);
  return results;
}
```

