function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  let state = 'closed';
  let failureCount = 0;
  let resetTimeout = null;
  let halfOpenLock = false;

  async function execute(...args) {
    if (state === 'open') {
      throw new Error('Circuit breaker is open');
    }
    if (state === 'half-open') {
      if (halfOpenLock) {
        throw new Error('Circuit breaker is half-open, another call in progress');
      }
      halfOpenLock = true;
    }

    try {
      const result = await fn(...args);
      onSuccess();
      return result;
    } catch (e) {
      onFailure();
      throw e;
    } finally {
      if (state === 'half-open') {
        halfOpenLock = false;
      }
    }
  }

  function onSuccess() {
    failureCount = 0;
    if (state === 'half-open') {
      state = 'closed';
    }
  }

  function onFailure() {
    failureCount++;
    if (state === 'half-open') {
      tripOpen();
    } else if (state === 'closed' && failureCount >= seuil) {
      tripOpen();
    }
  }

  function tripOpen() {
    state = 'open';
    if (resetTimeout) clearTimeout(resetTimeout);
    resetTimeout = setTimeout(() => {
      state = 'half-open';
