function remplirMatrice(grille, x, y, nouvelleValeur) {
  // Vérifications de base
  if (!grille || !Array.isArray(grille) || grille.length === 0) return grille;
  if (!Array.isArray(grille[0])) return grille;

  const lignes = grille.length;
  const colonnes = grille[0].length;

  // Vérifier que les coordonnées sont valides
  if (x < 0 || x >= colonnes || y < 0 || y >= lignes) return grille;

  const valeurOriginale = grille[y][x];

  // Si la nouvelle valeur est identique, rien à faire
  if (valeurOriginale === nouvelleValeur) return grille;

  // Utiliser une pile pour DFS itératif (évite les limites de récursion)
  const pile = [[x, y]];
  const visites = new Set();

  while (pile.length > 0) {
    const [cx, cy] = pile.pop();
    const cle = `${cx},${cy}`;

    if (visites.has(cle)) continue;
    visites.add(cle);

    // Vérifier les limites et la valeur
    if (cx < 0 || cx >= colonnes || cy < 0 || cy >= lignes) continue;
    if (grille[cy][cx] !== valeurOriginale) continue;

    // Remplacer la valeur
    grille[cy][cx] = nouvelleValeur;

    // Ajouter les 4 voisins (haut, bas, gauche, droite)
    pile.push([cx + 1, cy]);
    pile.push([cx - 1, cy]);
    pile.push([cx, cy + 1]);
    pile.push([cx, cy - 1]);
  }

  return grille;
}
