function dijkstra(graphe, depart) {
  // Collect all nodes (keys and neighbors)
  const nodes = new Set();
  for (const node in graphe) {
    nodes.add(node);
    for (const neighbor in graphe[node]) {
      nodes.add(neighbor);
    }
  }

  const distances = {};
  for (const node of nodes) {
    distances[node] = Infinity;
  }
  distances[depart] = 0;

  // Min-heap priority queue
  const pq = [[0, depart]];
  function push(item) {
    pq.push(item);
    let i = pq.length - 1;
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (pq[parent][0] <= pq[i][0]) break;
      [pq[parent], pq[i]] = [pq[i], pq[parent]];
      i = parent;
    }
  }
  function pop() {
    if (pq.length === 0) return null;
    const min = pq[0];
    const end = pq.pop();
    if (pq.length > 0) {
      pq[0] = end;
      let i = 0;
      while (true) {
        let left = 2 * i + 1;
        let right = 2 * i + 2;
        let smallest = i;
        if (left < pq.length && pq[left][0] < pq[smallest][0]) smallest = left;
        if (right < pq.length && pq[right][0] < pq[smallest][0]) smallest = right;
        if (smallest === i) break;
        [pq[i], pq[smallest]] = [pq[smallest], pq[i]];
        i = smallest;
      }
    }
    return min;
